using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class B3Import {
 const string A="Assets/Afrer_Seconds/05.Model/",E=A+"Environment/B3/",P=A+"Props/B3/";static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static Dictionary<string,Material> mats=new Dictionary<string,Material>();
 static Material Save(Material m,string folder){string p=folder+"Materials/"+m.name+".mat";var old=AssetDatabase.LoadAssetAtPath<Material>(p);if(old){EditorUtility.CopySerialized(m,old);UnityEngine.Object.DestroyImmediate(m);m=old;}else AssetDatabase.CreateAsset(m,p);m.enableInstancing=true;EditorUtility.SetDirty(m);return m;}
 static Texture2D Tex(string n)=>AssetDatabase.LoadAssetAtPath<Texture2D>(P+"Textures/"+n+".png");
 public static object Run(){if(Application.isPlaying)throw new Exception("Edit required");AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);foreach(string file in Directory.GetFiles(P+"Textures","*.png").Where(f=>new[]{"B3_Display_","B3_Labels","B3_CaseWear_","BS_Guide_","B3_CryogenicDewar_","B3_SealedSampleCarrier_"}.Any(n=>Path.GetFileName(f).StartsWith(n)))){string p=file.Replace('\\','/');bool normal=p.Contains("_0_2");var t=(TextureImporter)AssetImporter.GetAtPath(p);t.textureType=normal?TextureImporterType.NormalMap:TextureImporterType.Default;t.sRGBTexture=!normal&&!p.Contains("MetalSmooth")&&!p.Contains("_0_1")&&!p.Contains("_0_3");t.mipmapEnabled=true;t.maxTextureSize=2048;t.anisoLevel=8;t.wrapMode=p.Contains("CaseWear")?TextureWrapMode.Repeat:TextureWrapMode.Clamp;t.textureCompression=TextureImporterCompression.CompressedHQ;t.alphaIsTransparency=p.Contains("Guide_");t.SaveAndReimport();}
 foreach(string p in AssetDatabase.FindAssets("t:Material",new[]{A+"Environment/B4/Materials"}).Select(AssetDatabase.GUIDToAssetPath)){var source=AssetDatabase.LoadAssetAtPath<Material>(p);if(!source.name.StartsWith("B4O_"))continue;string key=source.name;var m=new Material(source){name="B3M_"+key.Substring(4)};if(key=="B4O_Coat")m.SetColor("_BaseColor",new Color(.32f,.35f,.38f));if(key=="B4O_Steel"){m.SetColor("_BaseColor",new Color(.37f,.40f,.43f));m.SetFloat("_Smoothness",.35f);}if(key=="B4O_Floor")m.SetColor("_BaseColor",new Color(.15f,.18f,.21f));mats[key]=Save(m,E);}
 foreach(var a in JArray.Parse(File.ReadAllText(R+"/SourceAssets/B3_FullFloor/varco_assets.json"))){string n=(string)a["name"];var m=new Material(Shader.Find("Universal Render Pipeline/Lit")){name=n+"_PBR_0"};m.SetColor("_BaseColor",Color.white);m.SetTexture("_BaseMap",Tex(n+"_0_0"));m.SetTexture("_BumpMap",Tex(n+"_0_2"));m.SetFloat("_BumpScale",.65f);m.SetTexture("_MetallicGlossMap",Tex(n+"_MetalSmooth"));m.SetFloat("_Smoothness",1);m.EnableKeyword("_NORMALMAP");m.EnableKeyword("_METALLICSPECGLOSSMAP");mats[m.name]=Save(m,P);}
 foreach(string file in Directory.GetFiles(P+"Textures","*.png")){string n=Path.GetFileNameWithoutExtension(file);if(!(n.StartsWith("B3_Display_")||n=="B3_Labels"||n.StartsWith("BS_Guide_")))continue;var m=new Material(Shader.Find("Universal Render Pipeline/Lit")){name=n};m.SetColor("_BaseColor",Color.white);m.SetTexture("_BaseMap",Tex(n));m.SetFloat("_Smoothness",.22f);if(n.Contains("Display")){m.SetTexture("_EmissionMap",Tex(n));m.SetColor("_EmissionColor",Color.white*.45f);m.EnableKeyword("_EMISSION");m.SetFloat("_SpecularHighlights",0);}if(n.Contains("Guide")){m.SetFloat("_AlphaClip",1);m.EnableKeyword("_ALPHATEST_ON");m.SetOverrideTag("RenderType","TransparentCutout");m.renderQueue=2450;}mats[n]=Save(m,P);}
 var colors=new[]{new Color(.22f,.26f,.28f),new Color(.34f,.36f,.34f),new Color(.19f,.22f,.24f),new Color(.46f,.48f,.44f),new Color(.30f,.32f,.34f),new Color(.38f,.39f,.36f)};for(int i=0;i<6;i++){var m=new Material(mats["B4O_Coat"]){name="B3_Case_"+i};m.SetColor("_BaseColor",colors[i]);m.SetTexture("_BaseMap",Tex("B3_CaseWear_Base"));m.SetTexture("_MetallicGlossMap",Tex("B3_CaseWear_MetalSmooth"));m.SetFloat("_Smoothness",1);m.EnableKeyword("_METALLICSPECGLOSSMAP");mats[m.name]=Save(m,P);}
 var guides=JObject.Parse(File.ReadAllText(R+"/SourceAssets/B3_FullFloor/guide_colors.json"));foreach(var kv in guides){ColorUtility.TryParseHtmlString("#"+(string)kv.Value,out var c);var m=new Material(Shader.Find("Universal Render Pipeline/Lit")){name="BS_Line_"+kv.Key};m.SetColor("_BaseColor",c);m.SetFloat("_Smoothness",.2f);mats[m.name]=Save(m,E);}
 var models=JObject.Parse(File.ReadAllText(R+"/SourceAssets/B3_FullFloor/models.json"));var paths=models.Properties().Select(k=>(string)k.Value["category"]).ToArray();var files=Directory.GetFiles(E,"BS_*.fbx").Concat(Directory.GetFiles(P,"BS_*.fbx")).Concat(new[]{P+"B3_CryogenicDewar.fbx",P+"B3_SealedSampleCarrier.fbx"}).Select(p=>p.Replace('\\','/')).ToArray();foreach(var p in files){var mi=(ModelImporter)AssetImporter.GetAtPath(p);mi.importAnimation=false;mi.importCameras=false;mi.importLights=false;mi.isReadable=true;mi.importNormals=ModelImporterNormals.Import;mi.importTangents=ModelImporterTangents.CalculateMikk;mi.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;foreach(var kv in mats)mi.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),kv.Key),kv.Value);mi.SaveAndReimport();}
 var cat=new List<object>();foreach(string p in AssetDatabase.GetAllAssetPaths().Where(p=>p.StartsWith(A+"Props/")&&p.EndsWith(".fbx")&&!Path.GetFileName(p).StartsWith("FL_")).Concat(files.Where(p=>p.StartsWith(E))).Distinct()){var g=AssetDatabase.LoadAssetAtPath<GameObject>(p);if(!g)continue;var rs=g.GetComponentsInChildren<Renderer>();if(rs.Length==0)continue;var b=rs[0].bounds;foreach(var r in rs.Skip(1))b.Encapsulate(r.bounds);var meshes=g.GetComponentsInChildren<MeshFilter>().Select(f=>f.sharedMesh).Where(m=>m).ToArray();int degenerate=0;foreach(var m in meshes){if(!m.isReadable)continue;var v=m.vertices;var ix=m.triangles;for(int i=0;i<ix.Length;i+=3)if(Vector3.Cross(v[ix[i+1]]-v[ix[i]],v[ix[i+2]]-v[ix[i]]).sqrMagnitude<1e-16f)degenerate++;}cat.Add(new{asset=p,name=Path.GetFileNameWithoutExtension(p),size=new[]{b.size.x,b.size.y,b.size.z},center=new[]{b.center.x,b.center.y,b.center.z},triangles=meshes.Sum(m=>(int)m.GetIndexCount(0)/3),degenerate,materials=rs.SelectMany(r=>r.sharedMaterials).Select(m=>m?m.name:"MISSING").Distinct()});}AssetDatabase.SaveAssets();File.WriteAllText(R+"/SourceAssets/B3_FullFloor/catalog.json",JsonConvert.SerializeObject(cat,Formatting.Indented));return new{newModels=files.Length,materials=mats.Count,catalog=cat.Count};}
}
